fn frame(t: i32) {
    let w: i32 = host::display::width();
    let tx: i32 = 30;
    let ty: i32 = 120;
    let tw: i32 = w - 60;
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut v: i32 = host::display::state_get(0);
    if down == 1 && py >= ty - 16 && py < ty + 20 {
        let mut rel: i32 = px - tx;
        if rel < 0 { rel = 0; }
        if rel > tw { rel = tw; }
        v = rel * 100 / tw;
        host::display::state_set(0, v);
    }
    host::display::clear(0x101010);
    host::display::fill_rect(tx, ty, tw, 4, 0x404040);
    host::display::fill_rect(tx, ty, v * tw / 100, 4, 0x00ff88);
    let hx: i32 = tx + v * tw / 100;
    host::display::fill_rect(hx - 6, ty - 10, 12, 24, 0xffffff);
    host::display::draw_string(30, 60, "VALUE", 0x808080, 1);
    host::display::draw_number(30, 76, v, 0xffffff, 3);
    host::display::present();
}
